with f as (select "Baggage_Weight_Basis","Baggage_Flight_Variation" from "Basic_Carrier_Record"."Operational_Flights" where "Operational_Flight_ID"='0d6daa41-c08e-4776-9753-f4319155ceff'), codes as (select unnest(array['F','C','W','Y']) code)
select jsonb_build_object('capturedAt',clock_timestamp(),'flightBaggageBasis',(select to_jsonb(f) from f),'assumptions',(select jsonb_agg(jsonb_build_object('classCode',codes.code,'selected',to_jsonb(a)) order by codes.code) from codes cross join f left join lateral (
select p.*,1 priority from "Basic_Carrier_Record"."Carrier_Planning_Assumptions" p where p."Carrier_IATA"='ZZ' and p."Class_Code"=codes.code and ((f."Baggage_Weight_Basis"='VARIATION' and p."Flight_Type_Variation"=f."Baggage_Flight_Variation") or (f."Baggage_Weight_Basis"<>'VARIATION' and p."Flight_Type_Variation" is null))
union all select p.*,2 from "Basic_Carrier_Record"."Carrier_Planning_Assumptions" p where f."Baggage_Weight_Basis"='VARIATION' and p."Carrier_IATA"='ZZ' and p."Class_Code" is null and p."Flight_Type_Variation"=f."Baggage_Flight_Variation"
union all select p.*,3 from "Basic_Carrier_Record"."Carrier_Planning_Assumptions" p where f."Baggage_Weight_Basis"='VARIATION' and p."Carrier_IATA"='ZZ' and p."Class_Code"=codes.code and p."Flight_Type_Variation" is null
union all select p.*,9 from "Basic_Carrier_Record"."Carrier_Planning_Assumptions" p where p."Carrier_IATA"='ZZ' and p."Class_Code" is null and p."Flight_Type_Variation" is null order by priority limit 1
) a on true),'packingFunctionDefinition',(select pg_get_functiondef(p.oid) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname='a350_baggage_piece_targets')) as snapshot
